export function buildHiTechCatalogComparison(device, allDevices) {
	const sameFamily = allDevices.filter((d) => d.id !== device.id && d.technologyFamily === device.technologyFamily).map((d) => ({
		...d,
		sharedSkinTypes: [],
		sharedCharacteristics: [],
		reason: "Ta sama rodzina technologii"
	}));
	const sameDowntime = allDevices.filter((d) => d.id !== device.id && d.downtimeProfile === device.downtimeProfile).map((d) => ({
		...d,
		sharedSkinTypes: [],
		sharedCharacteristics: [],
		reason: "Ten sam profil downtime"
	}));
	const overlappingConcerns = allDevices.filter((d) => d.id !== device.id && d.suitableSkinTypes.some((st) => device.suitableSkinTypes.includes(st))).map((d) => ({
		...d,
		sharedSkinTypes: d.suitableSkinTypes.filter((st) => device.suitableSkinTypes.includes(st)),
		sharedCharacteristics: [],
		reason: "Pokrywa się w typach skóry"
	}));
	return {
		reportFit: {
			level: device.rankingWeight > 2 ? "primary" : "secondary",
			title: device.rankingWeight > 2 ? "Główna rekomendacja" : "Opcja uzupełniająca",
			description: device.rankingWeight > 2 ? "Urządzenie jest często wybierane jako pierwsza linia terapii ze względu na wysoką wagę rankingową." : "Urządzenie pełni rolę wspierającą lub alternatywną w protokołach zabiegowych."
		},
		sameFamily,
		sameDowntime,
		overlappingConcerns
	};
}

